// Maintained source. Generated byte-identically into Pi's sealed resource pack.
// Reads the owner's ~/.agents/AGENTS.md once per process and appends it to the
// prompt. Cheap file checks only: a regular file, not a symlink, owned by this
// user, at most 128 KiB, valid UTF-8. Path and SHA-256 are shown on request
// (/shared-home), not in every prompt.
import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';

export function snapshotOwner(home) {
  const file = typeof home === 'string' ? path.join(home, '.agents/AGENTS.md') : '(HOME unavailable)';
  try {
    if (!path.isAbsolute(home)) throw Error('absolute HOME required');
    const fd = fs.openSync(file, fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW | fs.constants.O_NONBLOCK);
    let bytes;
    try {
      const stat = fs.fstatSync(fd);
      if (!stat.isFile() || stat.uid !== process.getuid()) throw Error('not a regular file owned by this user');
      if (stat.size > 128 * 1024) throw Error('over 128 KiB');
      bytes = fs.readFileSync(fd);
    } finally { fs.closeSync(fd); }
    const text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
    if (!text.trim()) throw Error('empty');
    return { status: 'loaded', path: file, sha256: createHash('sha256').update(bytes).digest('hex'), text };
  } catch (error) {
    return { status: error.code === 'ENOENT' ? 'missing' : 'refused', path: file,
      reason: error.code === 'ENOENT' ? 'run vertrice-agents init and review the file to use it' : `not loaded: ${error.code === 'ELOOP' ? 'a symlink' : error.message}` };
  }
}

export default function sharedInstructions(pi) {
  let snapshot;
  const capture = ctx => {
    if (!snapshot) {
      snapshot = snapshotOwner(process.env.HOME);
      if (ctx?.hasUI) ctx.ui.setStatus('vertrice-shared-home', snapshot.status === 'loaded' ? 'shared home: loaded' : `shared home: ${snapshot.status}`);
      if (snapshot.status === 'refused') (ctx?.hasUI ? m => ctx.ui.notify(m, 'warning') : console.error)(`Shared home: ${snapshot.path} ${snapshot.reason}`);
    }
    return snapshot;
  };
  pi.registerCommand?.('shared-home', {
    description: 'Show which shared owner instructions this session loaded',
    handler: async (_args, ctx) => {
      const s = capture(ctx);
      ctx.ui.notify(s.status === 'loaded' ? `Loaded ${s.path} (SHA-256 ${s.sha256}); edits apply to the next process` : `${s.path}: ${s.status}; ${s.reason}`, 'info');
    },
  });
  pi.on('session_start', (_event, ctx) => { capture(ctx); });
  pi.on('before_agent_start', (event, ctx) => {
    const data = capture(ctx);
    if (data.status !== 'loaded') return;
    return { systemPrompt: event.systemPrompt + '\n\nOwner instructions from ~/.agents/AGENTS.md:\n' + data.text };
  });
}
